/*
 * Fastr's service worker. Requirements 15.2, 15.3, 15.4, and the push half of Requirement 7.
 *
 * Hand-written rather than generated by a plugin, because it is about sixty lines of policy and the policy is
 * the interesting part. Three rules:
 *
 *   1. **The app shell is network-first.** A cached shell that never updates is the classic PWA failure: the
 *      user runs last month's JavaScript against this month's database. So the network wins when it is
 *      available, and the cache is the fallback.
 *   2. **Hashed assets are cache-first.** Their filenames contain a content hash, so a given URL can never
 *      change meaning. Revalidating them would be pure waste.
 *   3. **Supabase is never cached.** Stale fasting data presented as current is worse than an error, and the
 *      offline timer is served from React Query's last result, not from here.
 */

const VERSION = 'fastr-v1';
const SHELL_CACHE = `${VERSION}-shell`;
const ASSET_CACHE = `${VERSION}-assets`;

const BASE = new URL(self.registration.scope).pathname;

/** Enough to open the app and show the last known timer state. */
const SHELL = [BASE, `${BASE}index.html`, `${BASE}manifest.webmanifest`, `${BASE}theme-boot.js`];

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL_CACHE);
      // `reload` so an install never populates the cache from an HTTP cache that is itself stale.
      await cache.addAll(SHELL.map((url) => new Request(url, { cache: 'reload' })));
      // Requirement 15.3's update flow: take over immediately rather than waiting for every tab to close. The
      // page is told, and asks before reloading.
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((name) => !name.startsWith(VERSION)).map((name) => caches.delete(name)),
      );
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  // Sent by the page when the user accepts a waiting update.
  if (event.data === 'skip-waiting') void self.skipWaiting();
});

function isAsset(url) {
  return url.pathname.startsWith(`${BASE}assets/`) || url.pathname.startsWith(`${BASE}icons/`);
}

self.addEventListener('fetch', (event) => {
  const { request } = event;

  // Only GET, and only this origin. A POST to Supabase must never be served from a cache, and replaying one
  // would be worse than failing.
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (isAsset(url)) {
    event.respondWith(
      (async () => {
        const cache = await caches.open(ASSET_CACHE);
        const hit = await cache.match(request);
        if (hit) return hit;
        const response = await fetch(request);
        if (response.ok) void cache.put(request, response.clone());
        return response;
      })(),
    );
    return;
  }

  // Navigations and everything else same-origin: network first, cache as the fallback.
  event.respondWith(
    (async () => {
      try {
        const response = await fetch(request);
        if (response.ok && request.mode === 'navigate') {
          const cache = await caches.open(SHELL_CACHE);
          void cache.put(`${BASE}index.html`, response.clone());
        }
        return response;
      } catch {
        const cache = await caches.open(SHELL_CACHE);
        // Any navigation falls back to the shell, because the app is a SPA and its router will resolve the
        // path once it is running.
        const hit =
          (await cache.match(request)) ??
          (request.mode === 'navigate' ? await cache.match(`${BASE}index.html`) : undefined);
        if (hit) return hit;
        throw new Error('offline and not cached');
      }
    })(),
  );
});

/*
 * Push. Requirement 7.
 *
 * The payload is composed by the sender from the shared plan and stage data, so nothing here needs to know
 * what a fasting stage is.
 */
self.addEventListener('push', (event) => {
  if (!event.data) return;

  let payload;
  try {
    payload = event.data.json();
  } catch {
    payload = { title: 'Fastr', body: event.data.text() };
  }

  event.waitUntil(
    self.registration.showNotification(payload.title ?? 'Fastr', {
      body: payload.body ?? '',
      icon: `${BASE}icons/icon-192.png`,
      badge: `${BASE}icons/badge.png`,
      // Without a tag, a user who opted into stage notifications collects six separate banners on a 24-hour
      // fast. With one, each replaces the last.
      tag: payload.tag ?? 'fastr',
      data: { url: payload.url ?? BASE },
      requireInteraction: false,
    }),
  );
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();

  event.waitUntil(
    (async () => {
      const target = event.notification.data?.url ?? BASE;
      const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });

      // Focus an open tab rather than opening a second one, which is what a user expects from tapping a
      // notification for an app they already have open.
      for (const client of windows) {
        if (client.url.includes(BASE)) return client.focus();
      }
      return self.clients.openWindow(target);
    })(),
  );
});
